"""Database session helpers."""

from dataclasses import dataclass


@dataclass
class QueryResult:
    rows: list[dict]


class DatabaseSession:
    """Tiny fake database session used by the fixture."""

    def execute(self, query: str, params: dict | None = None) -> QueryResult:
        return QueryResult(rows=[])

    def fetch_one(self, query: str, params: dict | None = None) -> dict | None:
        return None

    def close(self) -> None:
        return None


def create_session() -> DatabaseSession:
    """Create a new database session."""
    return DatabaseSession()


def session_scope() -> DatabaseSession:
    """Return a scoped session object."""
    return create_session()

"""Domain event primitives."""

from dataclasses import dataclass
from typing import Callable


ORDER_CANCELLED = "order.cancelled"
PAYMENT_WEBHOOK_ACCEPTED = "billing.webhook.accepted"
INVOICE_RETRY_REQUESTED = "billing.invoice.retry_requested"


@dataclass(frozen=True)
class EventEnvelope:
    """Event wrapper shared by producers and consumers."""

    name: str
    payload: dict


class EventBus:
    """In-memory event bus for the fixture."""

    def __init__(self) -> None:
        self._handlers: dict[str, list[Callable[[EventEnvelope], None]]] = {}

    def subscribe(self, name: str, handler: Callable[[EventEnvelope], None]) -> None:
        self._handlers.setdefault(name, []).append(handler)

    def publish(self, event: EventEnvelope) -> None:
        for handler in self._handlers.get(event.name, []):
            handler(event)

